const D = { density:.5, scale:1, energy:.6, speed:1, hue:15, x:.5, y:.4, style:'dot', pop:.6, act:'bloom', seed:0 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const clp=(v,a,b)=>Math.max(a,Math.min(b,v)), TAU=Math.PI*2, PIc=Math.PI;
const md=(a,n)=>((a%n)+n)%n;
const ez=t=>{t=clp(t,0,1);return t*t*(3-2*t);};
const fr=i=>{const s=Math.sin(i*127.1+P.seed*311.7)*43758.5453;return s-Math.floor(s);};
if(S.lastBeat==null||K.beat<S.lastBeat)S.lastBeat=K.beat; S.lastBeat=K.beat;

const W=width,Hh=height,u=Math.min(W,Hh);
const style=P.style;
const dot=style==='dot', ring=style==='ring', halftone=style==='halftone', noir=style==='noir';
const en=clp(P.energy,0,1)*(.5+.7*K.intensity);
const dens=clp(P.density,0,1);
const hue=md(P.hue,360);

// background per style discipline
let bgH,bgS,bgB;
if(dot){ bgH=md(hue+205,360); bgS=24; bgB=88; }        // warm poster paper vs bold dots
else if(ring){ bgH=md(hue+180,360); bgS=30; bgB=14; }  // dark, schematic rings glow
else if(halftone){ bgH=45; bgS=8; bgB=90; }            // newsprint cream
else { bgH=hue; bgS=35; bgB=7; }                        // noir near-black

// ---- cached packing geometry (keyed on size/seed/density bucket) ----
const dB=Math.round(dens*6);
const key=W+'x'+Hh+'|'+P.seed+'|'+dB;
if(S.key!==key){
  S.key=key;
  const N=Math.min(150, Math.round(14+dens*150));
  const pts=[];
  for(let i=0;i<N;i++){ pts.push({x:fr(i*7.3+1)*W, y:fr(i*11.9+2)*Hh, ph:fr(i*3.7+5), tone:fr(i*5.9+9)}); }
  for(let i=0;i<N;i++){
    const a=pts[i]; let r=Math.min(a.x,W-a.x,a.y,Hh-a.y);
    for(let j=0;j<N;j++){ if(j===i)continue; const b=pts[j]; const d=Math.hypot(a.x-b.x,a.y-b.y)*0.5; if(d<r)r=d; }
    a.r=Math.max(u*0.006, r);
  }
  S.pts=pts;
}
const pts=S.pts;

// ---- LIVE COMPOSITE ----
noStroke();
background(bgH,bgS,bgB);

// per-section palette shift (dot-poster rotates through a limited set)
const sec=Math.floor(md(K.section,8));
const offs=[0,34,-30,66,150,200];
const growRate=0.11*P.speed, sc=clp(P.scale,.3,1.8);
const lx=P.x*W, ly=P.y*Hh;
const popAmt=clp(P.pop,0,1);
const bassPop = popAmt*(A.bass*0.8 + K.pulse*0.35);

for(let i=0;i<pts.length;i++){
  const c=pts[i];
  // grow/pop life cycle: L wraps 0..1 (grow then pop). K.t term => never re-phases.
  let L = md(K.beat*growRate + K.t*0.02*P.speed + c.ph, 1);
  if(P.act==='breathe') L = 0.5+0.5*Math.sin((K.beat*growRate+K.t*0.02+c.ph)*TAU);
  let gf = ez(clp(L*1.3,0,1));
  if(P.act==='pop'){ gf *= clp(1.15-L*0.6,0,1.15); } // sharper snap-and-fall
  gf *= (0.9+0.16*K.swell) + bassPop*(0.4+0.6*c.tone);
  const r = c.r*sc*gf;
  if(r<u*0.004) continue;
  const hcol = md(hue + offs[(i+sec)%offs.length] + K.t*1.6, 360);
  const bright = clp((noir?70:88) + 12*Math.sin(K.t*0.4+c.ph*TAU), 0, 100);

  if(ring){
    noFill(); const nr=3;
    for(let k=1;k<=nr;k++){ const rr=r*(k/nr); stroke(hcol, 70, bright, 70); strokeWeight(clp(r*0.05,0.6,3)); circle(c.x,c.y,rr*2); }
    stroke(hcol,40,100,40); strokeWeight(clp(r*0.05,0.6,3)); noFill(); // subtle inner glow ring already drawn
  } else if(halftone){
    // CMYK-ish misregistered stack (print halftone tell)
    const off=r*0.10*(1+0.5*Math.sin(K.t*0.6+i));
    noStroke();
    fill(md(hcol+180,360), 65, 95, 45); circle(c.x-off,c.y+off, r*2);
    fill(md(hcol+40,360), 70, 98, 45); circle(c.x+off,c.y, r*2);
    fill(hcol, 78, 96, 55); circle(c.x,c.y-off*0.7, r*2*0.9);
  } else if(noir){
    // chiaroscuro sphere — form from light only, no outline
    const dx=(lx-c.x), dy=(ly-c.y), dl=Math.hypot(dx,dy)+1;
    const ox=dx/dl*r*0.32, oy=dy/dl*r*0.32;
    noStroke();
    fill(hue, 40, 10, 100); circle(c.x,c.y, r*2);
    fill(hcol, 45, 42, 90); circle(c.x+ox*0.4, c.y+oy*0.4, r*1.5);
    fill(hcol, 30, 92, 90); circle(c.x+ox, c.y+oy, r*0.8);
    fill(hcol, 12, 100, 70); circle(c.x+ox*1.35, c.y+oy*1.35, r*0.34);
  } else {
    // dot poster — bold flat fill + concentric contrast ring
    noStroke(); fill(hcol, 72, bright, 100); circle(c.x,c.y, r*2);
    noFill(); stroke(md(hcol+ (c.tone>0.5?18:-18),360), 78, bright*0.65, 100); strokeWeight(clp(r*0.10,0.8,4)); circle(c.x,c.y, r*1.28);
  }
}

// bass bloom flash — partial additive wash centered on anchor (never full-frame)
if(en>0.02){
  blendMode(ADD);
  const fl=(K.pulse*0.5 + A.bass*0.9)*en;
  noStroke(); fill(md(hue+ (sec*20),360), 55, 100, 10*fl);
  circle(lx, ly, u*(0.4+0.6*fl));
  blendMode(BLEND);
}
drawingContext.shadowBlur=0;
